    title: "Chat-Assistent: fragen, an- oder abmelden und Termine per Chat",
    categoryId: "settings",
    keywords: [
      "assistent", "chat", "ki", "ai", "künstliche intelligenz", "fragen", "frag", "anwesenheit", "quote",
